      anger: () => `<g transform="translate(110 140) scale(1.7)" stroke="#d9443c" stroke-width="22" stroke-linecap="round" fill="none"><path d="M-40-10q30 0 30-30M10-40q0 30 30 30M40 10q-30 0-30 30M-10 40q0-30-30-30"/></g>`,
